/* Tradex help · ERP · Automation & exceptions (erp-automation.html) */
TX.help.add({
  "page": { t: "Automation & exceptions", k: "Page guide",
    what: "The control room for Tradex's automatic rules: what each rule does, how its runs went, the cases the rules could not finish on their own (exceptions), and the decisions waiting for someone with authority (approvals).",
    why: "Rules take routine, predictable work off staff — reserving stock after a payment, booking couriers, sending status messages. This page keeps every rule safe: each one has a named owner, can be stopped at once, is never allowed to make the decisions reserved for people, and hands anything unusual to a person with a deadline.",
    read: ["<b>Summary tiles</b> (top) — how many rules are running, how many runs today, how reliable they are, the estimated staff time saved, and how many exceptions and approvals are open.",
      "<b>Estimated staff hours saved per week</b> — the measured value of the rules over time.",
      "<b>Health right now</b> — anything failing or paused at this moment, with a button to the evidence.",
      "<b>Tabs</b> — Rules (the catalogue), Job runs (every execution), Exceptions (cases for people) and Approvals (decisions above someone's limit).",
      "Clicking a rule opens the <b>rule view</b> with its full definition, recent runs, change history and kill switch."],
    do: ["Check <b>Health right now</b> first: a paused rule or a failed import needs its owner.",
      "Work the <b>Exceptions</b> tab from the top (most severe first, then the earliest due).",
      "Decide the approvals waiting on you in the <b>Approvals</b> tab — every decision needs a reason.",
      "Stop a single rule with its kill switch if it gives wrong results; use <b>Pause automation…</b> only for an incident that affects several rules."],
    next: "Exceptions and approvals are resolved here or on the page the record belongs to (orders, stock, returns, payments). The owner gets a daily digest (rule A19) with the items above staff authority; routine items stay in staff queues.",
    notes: ["Phase 1 rules are deterministic: fixed, written rules that give the same result for the same input. No AI is used in Phase 1.",
      "Who may stop, resume, enable or change a rule, and who may use the global pause, is still to be confirmed by the business.",
      "Names, times, counts, percentages and ₹ values on this page are sample data."],
    map: [["rule-basics", "What every rule must have"], ["value-chart", "Value measured week by week"], ["health", "What is failing right now"],
      ["tab-rules", "The rule catalogue"], ["tab-runs", "Every run and its evidence"], ["tab-exceptions", "Cases handed to people"],
      ["tab-approvals", "Decisions waiting for authority"], ["d-rule", "One rule in detail"], ["m-pauseall", "Global pause and incident mode"], ["m-propose", "Asking for a new rule"]],
    terms: ["rule-codes", "exception", "approval", "idempotency", "job-queue", "kill-switch", "phase", "ai"] },

  "rule-basics": { t: "Deterministic rules", k: "Guide",
    what: "Every automation on this page is a fixed rule written in advance: <i>when</i> something happens (a payment arrives, stock drops below a level, a time is reached), <i>then</i> the system does one defined action. Given the same input, a rule always does the same thing.",
    why: "Predictable rules can be tested, explained and stopped. The blueprint recommends a validated import, a barcode scan or a fixed rule rather than AI wherever those solve the problem reliably.",
    lists: [{ h: "What every rule must have", items: [
      ["Owner", "A named team and person responsible for the outcome and for the rule's exceptions."],
      ["Idempotency key", "A unique key for each piece of work, so the same event arriving twice has an effect only once."],
      ["Retry policy", "How often and how quickly a failed attempt is tried again before a person is asked to help."],
      ["Human boundary", "What the rule is never allowed to decide on its own — for example refunds, cancellations or overriding a hold."],
      ["Kill switch", "A switch that stops the rule at once and moves its waiting work to a person."]] }],
    notes: ["Before a rule is switched on in production, every field of the automation template is filled in, the rule is dry-run on staging and the owner approves it."],
    terms: ["idempotency", "kill-switch", "ai", "staging-env"], rel: ["d-template"] },
  "reviewer": { t: "Rule reviewer", k: "Setting",
    what: "The person named to review how the rules perform at a fixed weekly slot, and who may switch off a rule that behaves badly.",
    why: "The blueprint asks who reviews automation performance and may disable a faulty rule. A rule nobody watches is not a control.",
    notes: ["The name and slot shown (Anita R. · Mondays 10:00) are sample values. The reviewer and the review cadence are still to be confirmed."] },
  "act-pauseall": { t: "Pause automation…", k: "Button",
    what: "Opens the global pause, which stops many rules at once during an incident instead of one kill switch at a time.",
    do: ["Choose <b>Non-critical only</b> or <b>Incident mode</b>.", "Enter the reason.", "Confirm. The owner and operations admin are notified and the action is recorded in the audit log."],
    notes: ["Use it rarely: paused automation means staff do the work by hand.", "On screen it needs the Owner or Operations admin (sample — who may use it is still open)."],
    rel: ["m-pauseall", "global-pause"], terms: ["audit"] },
  "act-propose": { t: "Propose a rule", k: "Button",
    what: "Opens a short form to suggest a new automation: the manual step it would replace, what should trigger it, who owns it, how often it happens and what it must never decide.",
    next: "The proposal gets a number (for example AP-019). A staff member is then observed doing the task for real before anything is built.",
    rel: ["m-propose"] },

  /* ------------------------------------------------------------ summary tiles */
  "kpi-active": { t: "Active rules", k: "Summary tile",
    what: "How many rules are switched on, out of all rules in the catalogue. The line underneath counts rules that are paused (stopped automatically or by a person) and off (never enabled).",
    rel: ["col-status"] },
  "kpi-runs": { t: "Runs today", k: "Summary tile",
    what: "How many times the rules have run today — every payment event, availability refresh or message sent counts as one run. The line underneath gives the total for the last 7 days.",
    rel: ["tab-runs"] },
  "kpi-success": { t: "Success rate", k: "Summary tile",
    what: "The share of runs that finished without an error today; the figure after \"7 d\" is the same for the last 7 days, across all rules.",
    read: "A run skipped as a duplicate counts as a success — skipping a repeat is the correct behaviour. A failed run is retried; if it still fails, it becomes an exception for the rule's owner.",
    notes: ["The rule view compares each rule with a target of 99% or more (sample target)."], rel: ["col-result"] },
  "kpi-saved": { t: "Staff time saved", k: "Summary tile",
    what: "An estimate of the staff hours the rules saved this week, after subtracting the time people spent handling the rules' exceptions.",
    read: "The arrow compares with the previous week. \"est.\" means estimated: the minutes saved per case come from a time study, not from timing every case.",
    rel: ["value-chart", "value-formula"] },
  "kpi-exceptions": { t: "Open exceptions", k: "Summary tile",
    what: "Cases the rules could not finish safely on their own and handed to a person, not yet resolved.",
    read: "<b>Critical</b> needs action first. <b>Owner-level</b> are exceptions only the owner (or a named alternate) can decide.",
    rel: ["tab-exceptions", "severity"], terms: ["exception"] },
  "kpi-approvals": { t: "Approvals waiting", k: "Summary tile",
    what: "Requests above someone's limit (discount, write-off, purchase order, price change…) waiting for a decision.",
    read: "<b>Overdue</b> requests passed their deadline and were escalated to the alternate approver. <b>On me</b> are the ones waiting for the signed-in user.",
    rel: ["tab-approvals"], terms: ["approval"] },

  /* ------------------------------------------------------------ value & health */
  "value-chart": { t: "Estimated staff hours saved per week", k: "Section",
    what: "A line chart of the estimated staff hours all enabled rules saved each week (weeks start on Monday), after subtracting the time spent handling their exceptions.",
    why: "The blueprint requires benefits to be measured, not assumed. The chart shows whether automation really removes work — a rule that causes many manual corrections can even have negative value.",
    read: ["Each point is one week. A rising line means more work is handled by rules.", "<b>Table view</b> shows the same numbers as a table.", "The formula underneath shows how the estimate is calculated; the note beside it says when the time study was last refreshed."],
    notes: ["When two rules save time on the same task, the saving is counted once.",
      "No ₹ value is shown: the cost of a staff hour must be agreed with the client, and who supplies the time study is still open.",
      "All figures on the chart are sample data."],
    rel: ["value-formula", "kpi-saved"] },
  "value-formula": { t: "Hours-saved formula", k: "Rule",
    what: "hours saved = number of cases × minutes saved per case ÷ 60 − hours spent handling exceptions.",
    read: "Worked example from the blueprint (illustrative only): 600 orders a month × 4 minutes saved = 40 hours; minus 8 hours of exception work = 32 net hours.",
    notes: ["Minutes saved per case come from watching staff do the task (a time study), refreshed regularly — monthly on the screen (sample).", "Extra sales are measured separately from staff-time savings."] },
  "health": { t: "Health right now", k: "Section",
    what: "A live summary of anything not working normally: rules paused, imports with rejected rows, settlements that did not fully match, and whether the global pause is on. The bottom row shows the state of the background job queue.",
    why: "Operations must see at a glance whether automation is running normally, and go straight to the evidence when it is not.",
    read: ["Red icon = stopped or failing; amber = partly done, a person is needed; green = normal.", "<b>Evidence</b> opens the Job runs tab at the failed run; <b>Open</b> opens the Exceptions tab.", "The time in the subtitle is when the summary was last refreshed; the pill on the right counts paused rules."],
    do: ["Open each red or amber item and check that its exception has an owner and a due time."],
    rel: ["auto-pause", "global-pause", "h-queue", "h-retries", "h-failed"], terms: ["job-queue", "http", "hsn"] },
  "auto-pause": { t: "Rule auto-paused", k: "Alert",
    what: "A rule the system stopped by itself because it failed several times in a row — here the courier's tracking service timed out three times, so 17 shipments have no fresh status.",
    why: "Stopping avoids hammering a failing provider and avoids showing customers wrong information. One exception is raised with the evidence — not one per shipment.",
    next: "The owner checks the evidence, moves the affected work to a manual process if customers are waiting, and resumes the rule once the provider has recovered.",
    rel: ["evidence", "m-resume"], terms: ["http"] },
  "global-pause": { t: "Global pause", k: "Status",
    what: "Whether automation as a whole is paused. <b>Off</b> means rules are running normally. The line below says when the global pause was last used, why, and for how long.",
    rel: ["m-pauseall"] },
  "h-queue": { t: "Oldest queued job", k: "Summary",
    what: "How long the oldest waiting background job has been in the queue. A few seconds is normal; a growing number means work is piling up.",
    notes: ["The Settings page (System tab) shows an alert that pages the on-call person when the oldest job is older than 10 minutes (sample threshold)."],
    terms: ["job-queue"] },
  "h-retries": { t: "Retries in the last 24 hours", k: "Summary",
    what: "How many failed attempts were tried again automatically in the last 24 hours, and how many of them then succeeded (recovered).",
    read: "Most retries recover by themselves — a short provider hiccup or a rate limit. Only the ones that do not recover become exceptions.",
    rel: ["backoff"] },
  "h-failed": { t: "Failed → exception", k: "Summary",
    what: "Jobs that used up all their retries and were handed to a person as an exception (by rule A38: one exception per job and record, with evidence and an owner).",
    rel: ["tab-exceptions"], terms: ["exception"] },

  /* ------------------------------------------------------------ Rules tab */
  "tab-rules": { t: "Rules", k: "Tab",
    what: "The catalogue of automation rules — one row per rule: what triggers it, what it does, who owns it, whether it is running, how reliable it is and how much time it saves.",
    why: "It is the single list of everything the system does on its own, so nobody is surprised by an automatic action and every rule has someone accountable for it.",
    read: ["<b>Rule</b> — code and name, the manual job it replaces, and its phase.", "<b>When → then</b> — the trigger and the action.", "<b>Status</b> — the on/off switch.",
      "<b>Runs 7 d · success</b>, <b>Saved</b> and <b>Last failure</b> — how it has performed.", "A pale amber row is paused; a grey row is off."],
    do: ["Filter by status or phase, or search by code, name, trigger or owner.", "Click a row to open the rule view: its full definition, recent runs and change history.", "Use the switch in the Status column to stop a rule — you will be asked for a reason."],
    lists: [{ h: "Rules in the catalogue", items: [
      ["A09 Payment webhook → payment state", "Records payment results sent by the payment provider, after checking they are genuine."],
      ["A05 Payment → reserve → pick task", "After a verified payment, turns the stock hold into an allocation and creates one pick task."],
      ["A06 Reservation expiry", "Releases stock held by abandoned checkouts or WhatsApp drafts after a set time."],
      ["A04 Stock movement → website availability", "Recalculates available-to-promise stock and refreshes the website and search after every committed stock movement."],
      ["A17 Low-stock replenishment suggestion", "Nightly, suggests purchase orders for items below their reorder point. A buyer approves every PO."],
      ["A01 Supplier import validation", "Checks supplier product files, finds duplicates and stages a preview. Nothing is published without a catalog reviewer."],
      ["A13 Courier booking & label", "Books the shipment and fetches the label and AWB once an order is packed and its serial verified."],
      ["A13.2 Courier tracking sync", "Pulls delivery status from the courier and updates the customer's tracking view."],
      ["A14 Order status notifications", "Sends approved email / SMS / WhatsApp updates, within consent and frequency limits."],
      ["A08 WhatsApp guided draft order", "Creates a draft order from a guided WhatsApp chat; the customer confirms price and address (pilot)."],
      ["A21 Stale supplier feed", "When a supplier's stock data is too old, asks for an update and stops promising that stock."],
      ["A19 Owner daily digest", "Sends the owner a daily summary of key figures and the exceptions above staff authority."],
      ["A16 Pending fulfilment chase", "Reminds staff about orders not picked or dispatched in time; escalates to the manager once."],
      ["A22 Return request routing", "Checks the return window, policy version and serial, then assigns the case to a review queue."],
      ["A10 Settlement matching", "Matches the payment provider's daily settlement to payments, fees and refunds."],
      ["A36 Margin leakage flag", "Flags order lines whose margin fell below the floor, for Finance to review (off — waiting for cost data)."],
      ["A38 Import / sync failure monitor", "Turns a job that used up its retries into one exception with evidence and an owner."]] }],
    next: "Automations planned for later phases are listed under the table (candidates not yet built).",
    notes: ["The A-codes come from the blueprint's automation catalogue. Times and limits in the triggers (15 minutes, 24 hours, 02:30…) are sample values set by the business — for example reservation expiry and supplier freshness."],
    terms: ["rule-codes", "phase", "atp", "reservation", "awb", "webhook", "settlement", "freshness"], rel: ["rule-filter", "col-status", "d-rule", "candidates"] },
  "rule-filter": { t: "Rule filters", k: "Filter",
    what: "Shows only some of the rules.",
    lists: [{ h: "Options", items: [
      ["All", "Every rule in the catalogue."], ["Active", "Rules switched on and running."],
      ["Paused", "Rules stopped for now — automatically after repeated failures, or by a person."],
      ["Off", "Rules that exist in the catalogue but were never enabled."],
      ["Failed in 7 d", "Rules with at least one failure or warning in the last 7 days."]] }],
    notes: ["The phase list beside it shows only 1A or 1B rules. The search box looks in codes, names, triggers, actions and owners."],
    terms: ["phase"] },
  "col-rule": { t: "Rule", k: "Column",
    what: "The rule's code (its A-number in the blueprint's automation catalogue) and name. Underneath: the manual job it replaces and its delivery phase (1A or 1B).",
    terms: ["rule-codes", "phase"] },
  "col-when": { t: "When → then", k: "Column",
    what: "<b>When</b> is the trigger — an event (a payment arrives), a schedule (nightly at 02:30) or a threshold (stock below the reorder point). <b>Then</b> is exactly what the rule does. Anything outside it is left to people.",
    notes: ["Times and limits in triggers are sample values set by the business."] },
  "col-owner": { t: "Owner", k: "Column",
    what: "The team and the person responsible for the rule's outcome. They receive its exceptions and decide whether it should be changed or stopped." },
  "col-status": { t: "Status", k: "Column",
    what: "Whether the rule is running. The switch stops or restarts it.",
    lists: [{ h: "Values", items: [
      ["On", "Running normally."],
      ["Paused · auto", "Stopped automatically after reaching its retry limit; waiting for its owner to resume it."],
      ["Off", "Never enabled in production (for example still waiting for the data it needs)."],
      ["Pilot", "Running for a limited group only — here WhatsApp ordering at one branch.", "b-info"]] }],
    do: ["Turning the switch off asks for a reason, then stops the rule.", "Turning a paused rule back on opens the resume check.", "Turning an off rule on sends an enable request — a staging dry run and owner approval come first."],
    rel: ["kill-switch", "m-kill", "m-resume"] },
  "col-success": { t: "Runs 7 d · success", k: "Column",
    what: "How many times the rule ran in the last 7 days, and the share of runs that succeeded.",
    read: "Green bar = 99% or more; amber = 95% to 99%; red = below 95%. A low rate on a rule that runs rarely (a daily import) can come from a single bad day." },
  "col-saved": { t: "Saved", k: "Column",
    what: "Estimated staff hours per week (h/wk) the rule saves, after the time spent on its exceptions.",
    rel: ["value-formula"] },
  "col-lastfail": { t: "Last failure", k: "Column",
    what: "When the rule last failed and why. Red = a failure that stopped work or was rejected; amber = partly done or handed to a person; grey = nothing recent (or the rule is not enabled)." },
  "candidates": { t: "Candidates not yet built", k: "Guide",
    what: "Automations from the blueprint catalogue planned for later phases, not part of Phase 1: follow-up of abandoned carts (A29), demand forecasting (A30), reading supplier invoices by OCR (A31), seller payouts (A33), and a product-question assistant and automated collection calls (A34/A35, Phase 3).",
    notes: ["Ideas that need judgement rather than a fixed rule are logged for Phase 2/3 review — they are not built as rules."],
    terms: ["phase", "ocr"] },

  /* ------------------------------------------------------------ Job runs tab */
  "tab-runs": { t: "Job runs", k: "Tab",
    what: "The log of individual rule executions (jobs): which rule ran, on which record, when, how long it took, which attempt it was, and the result.",
    why: "When something goes wrong this is the evidence: every run is recorded with its outcome, so failures are traced and fixed rather than guessed at.",
    read: ["The buttons above the table show only failed, retrying, partial or skipped runs; the rule list and the time buttons narrow it further.", "The highlighted row is the one whose evidence is shown under the table.", "Under the table, the <b>failed job</b> panel tells the full story of one failure: timeline, request and response, and checks."],
    do: ["Look at failed and partial runs first.", "Open the evidence of a failure, then retry it, move the work to a manual process, or resume the rule once the cause is fixed."],
    lists: [{ h: "Filters", items: [
      ["Failed", "Runs that ended in an error."], ["Retrying", "Runs waiting for their next automatic attempt."],
      ["Partial", "Runs that completed some records and sent the rest to a person."],
      ["Skipped (duplicate)", "Runs that found the work already done and did nothing — the idempotency key at work."]] }],
    notes: ["Logs are kept 90 days and failure evidence 1 year (sample values — retention is still to be decided)."],
    terms: ["job-queue", "idempotency"], rel: ["col-result", "evidence", "backoff"] },
  "backoff": { t: "Retry with backoff", k: "Rule",
    what: "When a run fails for a temporary reason it is tried again after 1 minute, then 2, then 4 — each wait twice as long, plus a small random extra delay (jitter) — up to 5 attempts. Some rules use a lower limit: the courier tracking sync stops after 3.",
    why: "Waiting longer between attempts gives a struggling provider time to recover, and the random delay stops many jobs retrying at the same moment.",
    notes: ["Permanent errors are not retried — for example a customer who opted out of WhatsApp, or a message with an invalid signature.", "The waits, attempt limits and log retention shown are sample values from the prototype."] },
  "col-run": { t: "Run", k: "Column", what: "The job number (JOB-…) of this execution. Quote it when asking for help or when linking evidence to an exception." },
  "col-entity": { t: "Entity", k: "Column",
    what: "The record the run worked on: an order (TXO-…), a reservation (R-…), a SKU, a supplier import (IMP-…), a settlement (SETL-…), a digest (DIG-…), a payment event, or a group of shipments.",
    terms: ["sku"] },
  "col-attempt": { t: "Attempt", k: "Column",
    what: "Which attempt this was, out of the maximum allowed — for example 2/4 is the second of four attempts; 3/3 means every attempt has been used.",
    rel: ["backoff"] },
  "col-result": { t: "Result", k: "Column",
    what: "How the run ended.",
    lists: [{ h: "Statuses", items: [
      ["Succeeded", "Done on the first try.", "s-ok"],
      ["Succeeded after retry", "An earlier attempt failed (for example a timeout) but a retry worked. The same idempotency key made sure nothing was booked twice.", "s-ok"],
      ["Skipped · duplicate", "The same event had already been processed, so the run did nothing — no second effect.", "s-muted"],
      ["Retrying in …", "Failed for a temporary reason (for example a rate limit); the next attempt is scheduled.", "s-warn"],
      ["Partial", "Part of the work was done; the rest (rejected rows, unmatched lines) went to a person.", "s-warn"],
      ["Failed → rule auto-paused", "Every attempt failed, so the rule stopped itself and raised one exception.", "s-bad"],
      ["Failed · not retried", "A permanent error a retry cannot fix (here the customer had opted out of WhatsApp); a fallback was used instead.", "s-bad"],
      ["Rejected", "The incoming message failed its security check (invalid signature), so it was not processed and a security alert was sent.", "s-bad"]] }],
    terms: ["idempotency", "webhook", "http"] },
  "evidence": { t: "Failed job evidence", k: "Section",
    what: "The full record of one failed run — here JOB-88213, the courier tracking sync — with the rule and version, its owner, the exception number and the provider's ticket.",
    why: "Each failure becomes one actionable incident with evidence, so the owner can see what happened without asking a developer.",
    read: ["<b>Timeline</b> (left) — each attempt, its error and the wait before the next try, ending with the automatic pause and the exception.",
      "<b>Customer impact</b> — what customers see, and what was not affected.",
      "<b>Technical record</b> (dark box) — the request sent (keys and passwords hidden), the provider's reply, and checks such as the provider's status page and the last successful sync."],
    do: ["Confirm the cause (here the courier's service was degraded).", "If customers are waiting, switch the affected shipments to manual tracking.", "When the provider has recovered, use <b>Resume rule…</b>. Use <b>Retry now</b> only for one extra attempt."],
    lists: [{ h: "Buttons", items: [
      ["Retry now", "Queues one more attempt by hand, outside the automatic retry limit; it is logged."],
      ["Switch to manual tracking", "Moves the affected shipments to the operations team's manual tracking queue."],
      ["Resume rule…", "Runs a health check, then restarts the rule."]] }],
    terms: ["http", "idempotency", "awb"], rel: ["ev-impact", "ev-retry", "ev-resume", "auto-pause"] },
  "ev-retry": { t: "Retry now", k: "Button",
    what: "Queues one extra attempt by hand, even though the automatic retry limit is used up. The attempt is logged as manual.",
    notes: ["Safe here because the tracking sync only reads data from the courier. For rules that change something at a provider (a booking, a payment), the provider is checked first so the action is never done twice."],
    terms: ["idempotency"] },
  "ev-resume": { t: "Resume rule…", k: "Button",
    what: "Opens the resume check for the paused rule: one test call runs first, and the rule restarts only if it passes.",
    rel: ["m-resume"] },
  "ev-impact": { t: "Customer impact", k: "Callout",
    what: "What customers experience because of this failure, and what was not affected. Here 17 shipments show \"Status update delayed\" on the tracking page instead of an outdated status; no orders, payments or stock were changed.",
    why: "How urgent a failure is depends on who it affects — this line answers that first." },

  /* ------------------------------------------------------------ Exceptions tab */
  "tab-exceptions": { t: "Exceptions", k: "Tab",
    what: "The queue of cases the rules could not finish safely on their own, each assigned to a person with a deadline. For every case it answers: what needs attention, why, who owns it, and by when.",
    why: "Routine work runs automatically and people handle only the unusual cases. One queue with owners and deadlines means nothing is forgotten, and the owner is not asked about things staff are allowed to decide.",
    read: ["Rows are sorted by severity, then by due time.",
      "Each row shows the severity, what happened and the evidence, the record involved, how long it has been open, who owns it, when it is due, who it goes to next if it is not resolved, and the actions allowed.",
      "Resolved rows (faded) stay visible with their resolution reason."],
    do: ["Start with <b>Critical</b>, then anything overdue (red due time).", "Use a recommended action button, or open the record on its own page.", "Record the resolution reason when you close an exception."],
    lists: [{ h: "Filters", items: [
      ["All teams", "Every open exception; the team list narrows it to one team."],
      ["Owner-level", "Cases above staff authority — they need the owner or a named alternate."],
      ["Mine", "Cases assigned to you."],
      ["Overdue", "Cases past their due time; they have moved up their escalation path."]] }],
    next: "Owner-level cases appear in the owner's daily digest; only urgent, material exceptions are sent to the owner straight away. Exceptions that keep coming back are flagged for a policy review.",
    notes: ["The severity scale, due times, default owners and escalation paths per exception type are still to be decided by the business."],
    terms: ["exception", "sla"], rel: ["severity", "col-escalation", "col-actions", "recurrence"] },
  "severity": { t: "Severity", k: "Statuses",
    what: "How serious an exception is. It sets the order of the queue.",
    lists: [{ h: "Values", items: [
      ["Critical", "Money or stock integrity at risk now — for example a payment captured but the order not confirmed. Act immediately.", "sev critical"],
      ["Serious", "A process is blocked or a significant decision is waiting — for example a failed refund or a paused rule.", "sev serious"],
      ["Warning", "Needs attention within its due time, with no immediate loss — for example a stale supplier feed.", "sev warning"],
      ["Resolved", "Closed; the resolution reason is kept.", "sev good"]] }],
    notes: ["These levels are the prototype's sample scale."] },
  "col-exc": { t: "Exception · evidence", k: "Column",
    what: "What went wrong (first line) and the facts behind it (second line) — for example the payment reference and times, the counted and system quantities, or the provider's error." },
  "col-exc-entity": { t: "Entity", k: "Column",
    what: "The record the exception is about, with its value where it has one: an order (TXO-…), job (JOB-…), return (RMA-…), bin and product, adjustment (ADJ-…), vendor (V-…), import (IMP-…), settlement (SETL-…), transfer (TR-…) or product.",
    terms: ["rma", "bin", "adjustment", "transfer"] },
  "col-assignee": { t: "Assignee", k: "Column",
    what: "The person and team who own the exception now and must resolve it or pass it on.",
    notes: ["Who covers when the assignee is absent is still open; on screen, overdue cases move up the escalation path."],
    terms: ["delegation"] },
  "col-due": { t: "Due", k: "Column",
    what: "The deadline for resolving the exception. Amber = due soon; red = overdue, and the exception has moved one step up its escalation path. <b>met</b> means it was resolved in time.",
    terms: ["sla"] },
  "col-escalation": { t: "Escalation path", k: "Column",
    what: "Who the exception goes to, in order, if it is not resolved in time — for example Finance → Owner at 1 hour. Some paths name an alternate with a lower limit, or say \"no alternate\" when only the owner may decide.",
    notes: ["Reminders escalate once — the rules avoid a stream of repeated alerts."], rel: ["col-due"] },
  "col-actions": { t: "Recommended actions", k: "Column",
    what: "The actions allowed for this exception, as buttons. <b>Decide…</b> opens the decision form; <b>Evidence</b> jumps to the failed job; other buttons start the named action (reserve an alternate unit, recount a bin, reassign, contact the vendor, reopen…).",
    notes: ["Only actions the rule's human boundary and your role allow are offered. Money actions such as refunds still go through finance maker–checker."],
    terms: ["maker-checker"], rel: ["m-approve"] },
  "recurrence": { t: "Recurring exceptions", k: "Rule",
    what: "Exceptions of the same kind that happen again and again (here 5 or more times a month) are flagged for a policy review. Resolved items keep their resolution reason.",
    why: "If a safe exception keeps happening, the better fix is to change the process or the limit — not to keep asking the owner every time.",
    notes: ["\"5 times a month\" is a sample trigger, to be confirmed."], rel: ["ma-recur"] },

  /* ------------------------------------------------------------ Approvals tab */
  "tab-approvals": { t: "Approvals", k: "Tab",
    what: "Requests above the requester's limit that wait for someone with authority: discounts, write-offs, purchase orders, price changes, vendor content, refund methods, dealer applications, payout accounts and stock transfers.",
    why: "Sensitive actions need a second person. Each request shows why approval is needed, its value, the deadline, who decides — and who decides if that person does not respond.",
    read: ["<b>Type</b> and <b>Item</b> — what is being requested and by whom.", "<b>Why approval is needed</b> — the limit or rule that triggered it.",
      "<b>Deadline</b> and <b>Approver → alternate</b> — who decides by when; overdue requests are escalated.", "<b>Decision</b> — the buttons for the approver."],
    do: ["Filter to <b>Waiting on me</b>.", "Open each request, check the evidence, and approve or reject with a reason.", "Tick \"This exception recurs\" when the same kind of request keeps coming, so the limit can be reviewed."],
    lists: [{ h: "Filters", items: [
      ["All", "Every open approval; the type list narrows it to one kind."], ["Waiting on me", "Requests where you are the approver."],
      ["Overdue / escalated", "Past the deadline and moved to the alternate approver."]] }],
    next: "The requester is told the decision and your reason. An approved action continues on its own page (orders, stock, purchasing, pricing, vendors).",
    notes: ["The ₹ and % limits are placeholders to be confirmed by the client (Settings → Thresholds).", "Which approval types are in release 1A and which in 1B is still open."],
    terms: ["approval", "maker-checker", "delegation"], rel: ["thresholds-link", "col-why", "col-approver", "m-approve", "apr-record"] },
  "thresholds-link": { t: "Approval thresholds", k: "Setting",
    what: "The limits that decide when a request needs approval, and by whom, are kept on the Settings page, Thresholds tab.",
    notes: ["Every value there is a placeholder until the client confirms it; until then these cases are routed to the owner."],
    terms: ["tbc"] },
  "col-apr-type": { t: "Type", k: "Column",
    what: "The kind of request.",
    lists: [{ h: "Types", items: [
      ["Discount override", "A discount larger than the requester's limit, or one that pushes the margin below the floor."],
      ["Stock write-off", "Removing damaged, lost or obsolete stock above a value limit."],
      ["Purchase order", "A PO above the buyer's limit."],
      ["Price list change", "A change to a whole dealer price list — an owner policy decision."],
      ["Price change", "A price change on one product above the limit."],
      ["Vendor content", "A material change submitted by a vendor, such as shorter warranty terms. The live listing stays unchanged until approved."],
      ["Refund method", "Refunding to a different method or account than the original payment."],
      ["Dealer application", "A new business account asking for dealer prices."],
      ["Payout account", "A new or changed vendor bank account."],
      ["Stock transfer", "Moving high-value stock between locations."]] }],
    terms: ["po", "price-list", "margin", "payout", "transfer", "adjustment"] },
  "col-why": { t: "Why approval is needed", k: "Column",
    what: "The reason the request could not go ahead on its own — which limit it exceeds, or which rule requires a second person.",
    why: "The blueprint requires recording why an approval was required, not just that someone clicked Approve." },
  "col-deadline": { t: "Deadline", k: "Column",
    what: "When the decision is due. Amber = due soon; red with a clock = overdue and escalated.",
    notes: ["The Settings page shows a default deadline of 4 working hours, escalating once to the named alternate; pending items are never approved automatically (sample values, still to be confirmed)."] },
  "col-approver": { t: "Approver → alternate", k: "Column",
    what: "Who decides (bold) and who decides instead if they do not respond in time. <b>Not set</b> in red means no alternate is named yet, so the request cannot escalate. Some alternates have a lower limit (for example \"≤ 10% only\").",
    terms: ["delegation"] },
  "col-decision": { t: "Decision", k: "Column",
    what: "The approver's buttons.",
    lists: [{ h: "Buttons", items: [
      ["Approve…", "Opens the decision form; approve with a reason."],
      ["Reject…", "Opens the same form; reject with a reason the requester will see."],
      ["Log call-back", "For bank-account changes: record that the vendor was called back on their registered number."],
      ["Cannot self-approve", "You made this request, so someone else must decide."]] }],
    rel: ["m-approve", "self-approve", "callback"] },
  "self-approve": { t: "Cannot self-approve", k: "Rule",
    what: "The person who made a request cannot approve it — here the owner's own price change goes to someone else.",
    why: "Separation of duties: risky actions need two different people.",
    notes: ["Which combinations are blocked and which only warned is still to be decided."],
    terms: ["maker-checker"] },
  "callback": { t: "Awaiting call-back", k: "Status",
    what: "A vendor's new bank account waits for a call-back: someone phones the vendor on the number already registered to confirm the change, before the checker approves it.",
    why: "Protects vendor payouts from fraudulent bank-detail changes.",
    terms: ["maker-checker", "payout"] },
  "apr-record": { t: "Decision record", k: "Rule",
    what: "Every approval decision stores the approver, the reason and the time in the audit log. Several requests may be reviewed together, but each keeps its own decision and history.",
    read: "\"Decided today\" counts today's decisions, including those staff made within their own delegated authority.",
    terms: ["audit"] },

  /* ------------------------------------------------------------ rule view (drawer) */
  "d-rule": { t: "Rule view", k: "Drawer",
    what: "Everything about one rule: its code, phase and status; the kill switch; four key numbers; and three tabs — the full definition, recent runs and change history.",
    read: ["The line under the name says which manual job the rule replaces, who owns it, and which approved version is running.",
      "The box at the top is the <b>kill switch</b>: it shows whether the rule is running and what stopping it would do.",
      "The four tiles show runs in the last 7 days, the success rate against its target, the estimated hours saved per week, and open exceptions."],
    do: ["Read the Definition tab to see exactly what the rule does — and does not do.", "Check Recent runs for failures.", "Stop, resume or request enabling with the kill-switch button.", "To change the rule use <b>Edit (needs approval)</b>; to test it use <b>Dry-run on staging</b>."],
    lists: [{ h: "Statuses", items: [
      ["Running", "Switched on and working.", "s-ok"],
      ["Paused automatically", "Stopped by the system after its retry limit; the time shows when.", "s-warn"],
      ["Off · not yet enabled", "Never switched on in production.", "s-muted"]] }],
    rel: ["kill-switch", "d-tab-def", "d-tab-runs", "d-tab-hist", "dk-runs", "dk-success", "dk-saved", "dk-exc", "d-dryrun", "d-edit"], terms: ["rule-codes", "phase"] },
  "kill-switch": { t: "Kill switch", k: "Button",
    what: "Stops or restarts the rule. The button and the switch beside it change with the rule's state.",
    lists: [{ h: "Buttons", items: [
      ["Stop rule", "For a running rule: asks for a reason, then stops new runs at once. Runs already in progress finish; queued work moves to the owner's manual queue."],
      ["Resume…", "For a paused rule: a health check runs first, then the rule processes the waiting work once (repeats are safe)."],
      ["Request enable", "For a rule that is off: sends an enable request. Every template field, a staging dry run and owner approval are needed first."]] }],
    notes: ["Nothing is replayed automatically when a stopped rule is switched back on, and nothing already done is undone.", "Every stop and restart is recorded in the audit log; the rule owner and reviewer are notified."],
    terms: ["kill-switch", "audit", "idempotency"], rel: ["m-kill", "m-resume"] },
  "dk-runs": { t: "Runs · 7 days", k: "Summary tile", what: "How many times this rule ran in the last 7 days." },
  "dk-success": { t: "Success", k: "Summary tile", what: "The share of this rule's runs that succeeded, compared with a target of 99% or more (sample target). \"Below 99% target\" appears when it falls short." },
  "dk-saved": { t: "Saved / week", k: "Summary tile", what: "Estimated staff hours this rule saves per week, after the time spent on its exceptions.", rel: ["value-formula"] },
  "dk-exc": { t: "Open exceptions", k: "Summary tile", what: "Exceptions raised by this rule that are still open.", rel: ["tab-exceptions"] },
  "d-tab-def": { t: "Definition", k: "Tab",
    what: "The rule's complete written specification, following the blueprint's automation template: the problem it solves, owner, trigger, inputs, preconditions, action, idempotency, failure behaviour, human boundary, audit, notification, KPI and how to disable it.",
    rel: ["d-template"] },
  "d-template": { t: "Automation template", k: "Guide",
    what: "The 13 fields every rule must have filled in before it can be switched on in production.",
    lists: [{ h: "Fields", items: [
      ["Business problem", "The manual step being replaced and what it costs (for example about 4 minutes per order)."],
      ["Owner", "The team and person accountable for the outcome and the exceptions."],
      ["Trigger", "What starts the rule: an event, a schedule, a threshold or a user action."],
      ["Inputs", "The records the rule reads, which fields must be present, and how fresh they must be."],
      ["Preconditions", "What must be true before it acts — permissions, approved status, payment and stock rules."],
      ["Action", "Exactly what it changes and which outside systems it calls."],
      ["Idempotency", "How a repeated event is recognised so it has no second effect."],
      ["Failure behaviour", "Retries, pausing, and how the work is recovered by hand."],
      ["Human boundary", "What the rule may never approve or decide."],
      ["Audit", "What is recorded for every run: actor, time, input versions, reason and outcome."],
      ["Notification", "Who is told, how urgently, and how repeats are limited."],
      ["KPI", "How success is measured: time saved, accuracy, success rate, exception rate."],
      ["Disable / rollback", "How to stop it safely and what happens to pending work."]] }],
    notes: ["Rules without their own detailed entries show the template's standard wording."],
    terms: ["kpi", "idempotency", "audit", "ssrf", "wismo"] },
  "d-tab-runs": { t: "Recent runs", k: "Tab",
    what: "The rule's latest runs, with start time, attempt, result and duration.",
    lists: [{ h: "Statuses", items: [
      ["Succeeded", "Done on the first try.", "s-ok"], ["Succeeded after retry", "Worked after an earlier attempt failed.", "s-warn"],
      ["Skipped · duplicate", "Already processed — no second effect.", "s-muted"], ["Failed → exception", "Every attempt failed; an exception was raised.", "s-bad"]] }],
    notes: ["A rule that was never enabled shows \"No runs yet\"."], rel: ["tab-runs"] },
  "d-tab-hist": { t: "Change history", k: "Tab",
    what: "Every version and state change of the rule, newest first: who approved each version and what changed, when it was paused or resumed and why, and when it first went live (after a staging dry run and user acceptance sign-off).",
    notes: ["A changed rule is released only after the owner approves the new version."],
    terms: ["uat", "audit", "staging-env"] },
  "d-dryrun": { t: "Dry-run on staging", k: "Button",
    what: "Runs the rule on staging (the test copy of the system) with recent real inputs, personal data masked, to see what it would do — without changing anything in the live system.",
    why: "Required before a rule is enabled or a changed version is released.",
    terms: ["staging-env"] },
  "d-edit": { t: "Edit (needs approval)", k: "Button",
    what: "Creates a draft of the rule's next version. The draft does not run until the owner approves it and it is released.",
    terms: ["audit"] },

  /* ------------------------------------------------------------ modals */
  "m-kill": { t: "Stop rule", k: "Modal",
    what: "Confirms stopping one rule with its kill switch.",
    read: "The warning says exactly what happens: new runs stop now, runs in progress complete, queued items move to the manual queue, the rule owner and reviewer are notified, and the change is audited.",
    do: ["Choose the reason.", "Add a note for the audit log (for example the provider's ticket number).", "Choose whether the rule should resume by itself.", "Click <b>Stop rule</b>."],
    next: "The rule shows as stopped; its waiting work sits in the owner's manual queue until the rule is resumed.",
    rel: ["mk-reason", "mk-until", "kill-switch"], terms: ["audit"] },
  "mk-reason": { t: "Reason", k: "Field",
    what: "Why the rule is being stopped. Required.",
    lists: [{ h: "Options", items: [
      ["Provider outage / degraded", "An outside service (courier, payment, messaging) is failing."],
      ["Wrong results observed", "The rule is doing something it should not — stop it before more harm."],
      ["Business policy change", "The rule no longer matches how the business works."],
      ["Planned maintenance", "A scheduled pause."], ["Other", "Explain it in the note."]] }] },
  "mk-until": { t: "Auto-resume", k: "Field",
    what: "Whether the rule restarts by itself later.",
    lists: [{ h: "Options", items: [
      ["Never — resume manually", "A person must resume it."],
      ["In 1 hour (with health check)", "Restarts after an hour, only if a test call succeeds."],
      ["At 18:00 today (with health check)", "Restarts at that time, only if a test call succeeds."]] }] },
  "m-resume": { t: "Resume rule", k: "Modal",
    what: "Restarts a paused rule safely — here the courier tracking sync.",
    do: ["Enter the reason (for example that the provider has recovered, with its ticket number).", "Click <b>Health check &amp; resume</b>."],
    next: "One test call runs first. If it passes, the rule resumes and the delayed items are processed once (17 shipments re-synced here). If it fails, the rule stays paused.",
    notes: ["Repeating this sync is safe because it only reads data from the provider."],
    rel: ["kill-switch", "evidence"] },
  "m-pauseall": { t: "Pause automation", k: "Modal",
    what: "Incident control: pauses many rules at once when something is wrong across the system. There are two levels.",
    why: "The blueprint's incident playbook says to contain the risk first — stop affected checkout or automation if stock or payment integrity is uncertain — and to reconcile before retrying anything.",
    do: ["Choose the level: <b>Non-critical only</b> or <b>Incident mode</b>.", "Enter the reason (for example what was observed at the provider).", "Click <b>Pause</b>. The owner and operations admin are notified; the action is audited."],
    next: ["While paused, staff do the paused work by hand.", "Before resuming: keep the evidence and reconcile the orders, payments, stock and jobs created during the incident.", "Afterwards, record the cause, the corrective action, an owner and a follow-up date."],
    notes: ["On screen this needs the Owner or Operations admin (sample — who may use it is still open)."],
    rel: ["pa-noncritical", "pa-incident", "global-pause"], terms: ["reconciliation", "audit"] },
  "pa-noncritical": { t: "Non-critical only", k: "Option",
    what: "Pauses notifications, digests, reminders, suggestions and imports. Payment webhooks, reservations and availability keep running, so stock and payments stay correct.",
    why: "Use it when messages or imports misbehave but the core of selling is fine.",
    terms: ["webhook", "reservation"] },
  "pa-incident": { t: "Incident mode", k: "Option",
    what: "Stops the automation that affects checkout. At the same moment checkout is switched to \"temporarily unavailable\". Events from providers (such as payment notifications) are stored and replayed only after reconciliation.",
    why: "Use it when stock or payment integrity is uncertain — for example duplicate payment notifications — so no sale is taken that the system cannot honour.",
    notes: ["This is the strongest control on the page: customers cannot buy while it is on."],
    terms: ["webhook", "reconciliation"] },
  "m-propose": { t: "Propose an automation rule", k: "Modal",
    what: "A request for a new rule. It follows the blueprint's order: observe the manual work first, estimate its value, then build and review.",
    do: ["Describe the manual step you see people doing, and how often.", "Pick the trigger type and the owner role.", "Add the observed cases per month and minutes saved per case if you know them.", "Write the human boundary — what the rule must never decide.", "Click <b>Submit proposal</b>."],
    next: "The proposal is logged (for example AP-019) and an observation session is scheduled: a staff member performs a real example while explaining their decisions. Each step is then classed as eliminate, simplify, integrate, automate or assist — only predictable steps become rules.",
    notes: ["Phase 1 rules are deterministic. Ideas that need judgement (compatibility answers, forecasting, invoice OCR) are logged for Phase 2/3 review, not built as rules."],
    rel: ["pp-problem", "pp-trigger", "pp-owner", "pp-cases", "pp-minutes", "pp-boundary", "value-formula"], terms: ["ocr", "phase"] },
  "pp-problem": { t: "Business problem", k: "Field",
    what: "The manual step people do today, described so it can be observed — who does it, how often and what it costs.",
    read: "Good: \"Branch staff phone the warehouse to check transfer arrival about 12 times a day.\" Too vague: \"Transfers are slow\" — vague problems can have very different causes." },
  "pp-trigger": { t: "Trigger", k: "Field",
    what: "What starts the rule.",
    lists: [{ h: "Options", items: [
      ["Event", "Something happens in the system (a payment arrives, stock moves)."],
      ["Schedule", "At a fixed time or interval (nightly, every 30 minutes)."],
      ["Threshold", "A value crosses a limit (stock below the reorder point, a feed older than 24 hours)."],
      ["Explicit user action", "A person presses a button to start it."]] }] },
  "pp-owner": { t: "Owner role", k: "Field", what: "The team responsible for the rule's outcome and its exceptions. Every rule must have one." },
  "pp-cases": { t: "Cases per month (observed)", k: "Field",
    what: "How many times the manual step happens per month, counted from real work — not a guess. Used with the minutes saved to estimate the rule's value.",
    rel: ["value-formula"] },
  "pp-minutes": { t: "Minutes saved per case", k: "Field",
    what: "How many staff minutes the rule would save each time, from watching the task being done.",
    rel: ["value-formula"] },
  "pp-boundary": { t: "Human boundary", k: "Field",
    what: "What the rule must never decide on its own — for example cancel a transfer, adjust stock or approve a refund. Required for every rule.",
    why: "It keeps judgement and authority with people and limits the harm a faulty rule can do." },
  "m-approve": { t: "Decision required", k: "Modal",
    what: "The form for approving or rejecting one request or owner-level exception. The grey box summarises what is being decided (type, item, value).",
    do: ["Read the summary; check the evidence on the record's own page if needed.", "Write the reason — it is stored in the audit log and sent to the requester.", "Tick the recurrence box if this kind of request keeps coming.", "Click <b>Approve</b> or <b>Reject</b>."],
    next: "The requester is notified with your reason; an approved action continues on its own page.",
    notes: ["An approval decides this case only — for example \"margin accepted once, not a new policy\"."],
    rel: ["ma-reason", "ma-recur"], terms: ["approval", "audit"] },
  "ma-reason": { t: "Reason", k: "Field", what: "Why you approve or reject. Required; stored permanently in the audit log and shown to the requester.", terms: ["audit"] },
  "ma-recur": { t: "Flag for policy review", k: "Field",
    what: "Tick this when the same kind of exception keeps coming back. It is then reviewed as a possible change to the process or threshold, instead of being decided case by case for ever.",
    rel: ["recurrence"] },

  /* ------------------------------------------------------------ page-local glossary terms (to merge into glossary.js) */
});
